"""Algebra and trigonometry contracts for Chapter 04."""

from __future__ import annotations

import numpy as np


class AlgebraTrigContractError(ValueError):
    """Raised when a quantity violates its mathematical contract."""


def _finite_scalar(value, name):
    result = float(value)
    if not np.isfinite(result):
        raise AlgebraTrigContractError(f"{name} must be finite")
    return result


def within_interval(value, lower, upper, tolerance=0.0):
    value = np.asarray(value, dtype=float)
    lower = _finite_scalar(lower, "lower")
    upper = _finite_scalar(upper, "upper")
    tolerance = _finite_scalar(tolerance, "tolerance")
    if value.size == 0 or not np.all(np.isfinite(value)):
        raise AlgebraTrigContractError("value must be finite and non-empty")
    if lower > upper or tolerance < 0:
        raise AlgebraTrigContractError("invalid interval")
    return bool(np.all(value >= lower - tolerance) and np.all(value <= upper + tolerance))


def softplus_stable(value):
    value = np.asarray(value, dtype=float)
    if not np.all(np.isfinite(value)):
        raise FloatingPointError("non-finite input")
    return np.maximum(value, 0.0) + np.log1p(np.exp(-np.abs(value)))


def polar_to_cartesian(radius, angle_rad):
    radius = _finite_scalar(radius, "radius")
    angle_rad = _finite_scalar(angle_rad, "angle_rad")
    if radius < 0:
        raise AlgebraTrigContractError("radius must be non-negative")
    return np.array([radius * np.cos(angle_rad), radius * np.sin(angle_rad)])


def cartesian_to_polar(vector):
    vector = np.asarray(vector, dtype=float)
    if vector.shape != (2,) or not np.all(np.isfinite(vector)):
        raise AlgebraTrigContractError("vector must be a finite 2-vector")
    if np.linalg.norm(vector) == 0:
        raise AlgebraTrigContractError("the zero vector has no direction")
    return float(np.linalg.norm(vector)), float(np.arctan2(vector[1], vector[0]))


def sinusoid_trajectory(t, offset, amplitude, omega, phase):
    t = np.asarray(t, dtype=float)
    if t.size == 0 or not np.all(np.isfinite(t)):
        raise AlgebraTrigContractError("t must be finite and non-empty")
    offset = _finite_scalar(offset, "offset")
    amplitude = _finite_scalar(amplitude, "amplitude")
    omega = _finite_scalar(omega, "omega")
    phase = _finite_scalar(phase, "phase")
    value = offset + amplitude * np.sin(omega * t + phase)
    velocity = amplitude * omega * np.cos(omega * t + phase)
    acceleration = -amplitude * omega ** 2 * np.sin(omega * t + phase)
    return value, velocity, acceleration


def dimensionless_error(position_error, orientation_error, position_limit, orientation_limit):
    position_error = _finite_scalar(position_error, "position_error")
    orientation_error = _finite_scalar(orientation_error, "orientation_error")
    position_limit = _finite_scalar(position_limit, "position_limit")
    orientation_limit = _finite_scalar(orientation_limit, "orientation_limit")
    if position_limit <= 0 or orientation_limit <= 0:
        raise AlgebraTrigContractError("limits must be positive")
    return (position_error / position_limit) ** 2 + (orientation_error / orientation_limit) ** 2


def demo():
    point = polar_to_cartesian(2.0, .7)
    radius, angle = cartesian_to_polar(point)
    values = softplus_stable([1000., -1000.])
    return {"radius": radius, "angle": angle, "softplus": values.tolist(),
            "dimensionless_error": dimensionless_error(.001, .01, .002, .02)}


if __name__ == "__main__":
    print(demo())
